package com.example.starter.rebate.domain;

/**
 * 单证状态：COLLECTED 已采集可配单；RELEASED 撤批后释放；LATE 结案后迟到（仅登记事件）。
 */
public enum DocStatus {
    COLLECTED,
    RELEASED,
    LATE
}

package com.example.starter.rebate.domain;

/**
 * 关联校验结果：PASS 换汇成本在 [5.0, 8.0]；DOUBT 越界转疑点。
 */
public enum ValidationResultCode {
    PASS,
    DOUBT
}

package com.example.starter.rebate.domain;

/**
 * 疑点状态：OPEN 待补充说明；EXPLAINED 已说明待复核；CLEARED 复核确认已解除。
 */
public enum DoubtStatus {
    OPEN,
    EXPLAINED,
    CLEARED
}

package com.example.starter.rebate.domain;

/**
 * 退库核销状态：CONSISTENT 到账一致（差额恰 0.5% 含内）；DISCREPANCY 超 0.5% 转人工。
 */
public enum RefundStatus {
    CONSISTENT,
    DISCREPANCY
}

