package com.example.starter.rebate.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;

/**
 * 采集请求：一张报关单与一张进项发票按商品编码配对。
 *
 * @param requestId     幂等键
 * @param declarationNo 报关单号
 * @param invoiceNo     进项发票号
 * @param hsCode        商品编码（报关单与发票关联键）
 * @param fobRmb        FOB 价（人民币元）
 * @param fobUsd        FOB 美元价（美元）
 */
public record CollectDocumentRequest(
        @NotBlank String requestId,
        @NotBlank String declarationNo,
        @NotBlank String invoiceNo,
        @NotBlank String hsCode,
        @NotNull @Positive BigDecimal fobRmb,
        @NotNull @Positive BigDecimal fobUsd
) {
}

package com.example.starter.rebate.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 退税率文库版本录入请求（合成数据）。
 *
 * @param requestId     幂等键
 * @param hsCode        商品编码
 * @param effectiveDate 生效日（UTC 日界）
 * @param rate          退税率（0~1 之间小数）
 */
public record SaveRateRequest(
        @NotBlank String requestId,
        @NotBlank String hsCode,
        @NotNull LocalDate effectiveDate,
        @NotNull @PositiveOrZero BigDecimal rate
) {
}

package com.example.starter.rebate.api;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 申报日有效的退税率文库版本。
 *
 * @param hsCode        商品编码
 * @param effectiveDate 命中版本生效日（UTC）
 * @param rate          退税率
 */
public record RateVersionResponse(
        String hsCode,
        LocalDate effectiveDate,
        BigDecimal rate
) {
}

package com.example.starter.rebate.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDate;
import java.util.List;

/**
 * 创建申报批次（数据采集后的关联校验环节）：建批次、关联单证并立即执行换汇成本校验。
 *
 * @param requestId   幂等键
 * @param batchNo     批次业务编号
 * @param declareDate 申报日（UTC 日界），决定退税率文库版本
 * @param documentIds 本次关联的已采集单证 ID 列表
 */
public record CreateBatchRequest(
        @NotBlank String requestId,
        @NotBlank String batchNo,
        @NotNull LocalDate declareDate,
        @NotEmpty List<@NotNull Long> documentIds
) {
}

package com.example.starter.rebate.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 疑点补充说明提交请求。
 *
 * @param requestId   幂等键
 * @param explanation 补充说明内容
 */
public record ExplainRequest(
        @NotBlank String requestId,
        @NotBlank String explanation
) {
}

package com.example.starter.rebate.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 正式申报请求：疑点复核确认与正式申报在同一事务内推进。
 * 列表中的疑点须为“已说明待复核”，且批次内不得残留未解除疑点，否则申报失败并整体回滚。
 *
 * @param requestId      幂等键
 * @param reviewDoubtIds 本次一并复核确认的疑点 ID 列表
 */
public record DeclareRequest(
        @NotBlank String requestId,
        @NotNull List<@NotNull Long> reviewDoubtIds
) {
}

