 * @param invoiceNo     迟到发票号
 * @param payload       原始报文
 * @param createdAt     登记时间（UTC）
 * @param replayed      是否幂等重放命中
 */
public record LateEventResponse(
        Long id,
        Long batchId,
        String declarationNo,
        String invoiceNo,
        String payload,
        Instant createdAt,
        boolean replayed
) {
}

