/**
 * 报关单号是否已挂在非作废（有效）批次下。撤批作废 VOID 不视为有效批次。
 */
public boolean isDeclarationInActiveBatch(String declarationNo) {
    Integer cnt = jdbc.queryForObject("""
                    SELECT COUNT(1) FROM rebate_document d
                    JOIN rebate_batch b ON b.id = d.batch_id
                    WHERE d.declaration_no = :declarationNo AND b.status <> 'VOID'
                    """,
            new MapSqlParameterSource("declarationNo", declarationNo), Integer.class);
    return cnt != null && cnt > 0;
}

