            for (Future<?> future : futures) {
                try {
                    future.get(20, TimeUnit.SECONDS);
                    success++;
                } catch (Exception e) {
                    assertThat(e).rootCause().isInstanceOf(BusinessConflictException.class);
                    conflict++;
                }
            }
